use super::*;
use super::super::desktop_preferences::DesktopPreferencesPage;
fn form(a:&Workspace)->Rc<DesktopPreferencesPage>{let widget=a.current_widget().unwrap();a.desktop_preference_pages.borrow().iter().find(|p|p.widget.upcast_ref::<gtk::Widget>()==&widget).unwrap().clone()}
fn open(a:&Rc<Workspace>)->Rc<DesktopPreferencesPage>{a.writing_view();wait(||a.desktop_preference_pages.borrow().iter().any(|p|p.loaded.get()&&a.current_widget()==Some(p.widget.clone().upcast())));form(a)}
fn save_form(a:&Rc<Workspace>,p:&Rc<DesktopPreferencesPage>)->Result<(),String>{let result=Rc::new(RefCell::new(None));let out=result.clone();a.save_current(move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some()&&!p.saving.get());let value=result.borrow_mut().take().unwrap();value}
fn settled(pane:&EditorPane){
    wait(||pane.pending.get()==0&&pane.frame.borrow()["width"]==pane.area.allocated_width()&&pane.area.allocated_width()>=240);
    let frame=pane.frame.borrow();let width=pane.area.allocated_width() as f64*15.;let cursor=frame["cursor"].as_array().unwrap();let x=cursor[0].as_f64().unwrap();assert!(x>=0.&&x<=width+1.,"Caret uses the allocated writing width");
    for rect in frame["selection"].as_array().into_iter().flatten(){let r=rect.as_array().unwrap();let x=r[0].as_f64().unwrap();let w=r[2].as_f64().unwrap();assert!(x>=0.&&x+w<=width+1.,"Selection rectangles fit their actual viewport");}
}
pub(super) fn run(binaries:&Path){
    let fixture=tempfile::tempdir().unwrap();let data=fixture.path().join("view-data");let cache=fixture.path().join("view-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();
    let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let project=rpc(&client,"create_novel",json!({"title":"Writing view"}));let pid=project["project"]["id"].as_str().unwrap();let sid=project["scene"]["id"].as_str().unwrap();let cid=project["scene"]["chapterId"].as_str().unwrap();
    let original=json!({"schemaVersion":1,"authorPreference":{"text":"مِ 中文 𠀀 👩🏽‍🚀"}});rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"settings","payload":original,"parent":null}));
    let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.open.get()&&p.pending.get()==0)&&a.desktop_preferences.loaded.get());let manuscript=a.active.borrow().clone().unwrap();
    edit(&manuscript,"View text مِ 中文 𠀀 👩🏽‍🚀 ");manuscript.operation(json!({"type":"command","command":"blockStyle","language":"ar","direction":"rtl","style":"heading"}),true);wait(||manuscript.pending.get()==0);manuscript.operation(json!({"type":"command","command":"selectAll"}),false);manuscript.operation(json!({"type":"command","command":"bold"}),true);wait(||manuscript.pending.get()==0);save(&a,&manuscript);let saved_scene=rpc(&a.client,"load_scene",json!({"sceneId":sid}));let document=saved_scene["scene"]["document"].clone();settled(&manuscript);let fill_width=manuscript.area.allocated_width();assert!(fill_width>500);
    let p=open(&a);p.mode.set_active_id(Some("bounded"));p.width.set_value(500.);p.direction.set_active_id(Some("rtl"));let marker=rpc(&a.client,"sync_cursor",json!({}));pump(Duration::from_millis(180));assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(a.window.direction(),gtk::TextDirection::Ltr);
    // Discard restores only the form; it does not activate its pending layout.
    p.discard();assert_eq!(p.mode.active_id().as_deref(),Some("fill"));assert_eq!(p.direction.active_id().as_deref(),Some("ltr"));assert!(!p.dirty.get());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);p.mode.set_active_id(Some("bounded"));p.width.set_value(500.);p.direction.set_active_id(Some("rtl"));
    select(&a,SaveChoice::Cancel);a.open_book();assert_eq!(a.current_widget(),Some(p.widget.clone().upcast()));assert!(p.dirty.get());p.width.set_text("500.5");assert!(save_form(&a,&p).is_err());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);p.width.set_value(500.);
    capture(&a,"notebook-writing-view.png");find_button(&p.widget,"Save view").unwrap().clicked();wait(||!p.saving.get()&&!p.dirty.get());assert_eq!(a.window.direction(),gtk::TextDirection::Rtl);assert_eq!(a.desk.sidebar.direction(),gtk::TextDirection::Rtl);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),saved_scene);assert_eq!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"settings"}))["payload"]["authorPreference"],original["authorPreference"]);
    a.open_scene(sid,false);wait(||a.current_widget()==Some(manuscript.widget.clone().upcast()));settled(&manuscript);assert_eq!(manuscript.area.allocated_width(),500);assert_eq!(manuscript.area.direction(),gtk::TextDirection::Ltr);assert_eq!(manuscript.frame.borrow()["document"],document);capture(&a,"notebook-bounded-writing-rtl.png");
    // Changing window size reflows actual allocation; rendering and hit testing use it.
    a.window.resize(700,650);pump(Duration::from_millis(220));settled(&manuscript);assert!(manuscript.area.allocated_width()<=500);assert_eq!(manuscript.frame.borrow()["document"],document);a.window.resize(1120,800);pump(Duration::from_millis(220));settled(&manuscript);assert_eq!(manuscript.area.allocated_width(),500);
    let second=rpc(&a.client,"create_scene",json!({"chapterId":cid,"scene":{"schemaVersion":1,"title":"Another scene","document":{"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"ltr","lang":"en"},"content":[{"type":"text","text":"Another مِ 中文"}]}]}}}));a.load_index();wait(||a.index.borrow()["scenes"].as_array().unwrap().len()==2);let second_id=second["id"].as_str().unwrap();a.open_scene(second_id,false);wait(||a.active.borrow().as_ref().is_some_and(|p|p.scene_id==second_id&&p.open.get()));let another=a.active.borrow().clone().unwrap();settled(&another);assert_eq!(another.area.allocated_width(),500);assert_eq!(another.frame.borrow()["document"],second["scene"]["document"]);
    // A second window gets the saved preference; its form supersedes an older edit.
    let stale=open(&a);stale.width.set_value(600.);let child=a.spawn_window();wait(||child.desktop_preferences.loaded.get());let fresh=open(&child);fresh.width.set_value(420.);fresh.direction.set_active_id(Some("ltr"));save_form(&child,&fresh).unwrap();let marker=rpc(&a.client,"sync_cursor",json!({}));assert!(save_form(&a,&stale).unwrap_err().contains("Conflict"));assert!(stale.dirty.get());assert_eq!(stale.width.value_as_int(),600);assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(a.window.direction(),gtk::TextDirection::Ltr);
    select(&a,SaveChoice::Discard);let detached_form=open(&a);detached_form.width.set_value(480.);a.detach_current();let detached=last_window();assert!(Rc::ptr_eq(&form(&detached),&detached_form));find_button(&detached_form.widget,"Save view").unwrap().clicked();wait(||!detached_form.saving.get()&&!detached_form.dirty.get());
    a.close();wait(||windows()==2);detached_form.mode.set_active_id(Some("fill"));save_form(&detached,&detached_form).unwrap();detached.open_scene(sid,false);wait(||detached.active.borrow().as_ref().is_some_and(|p|p.open.get()));let last=detached.active.borrow().clone().unwrap();settled(&last);assert!(last.area.allocated_width()>480);assert_eq!(rpc(&detached.client,"load_scene",json!({"sceneId":sid})),saved_scene);
    detached.close();wait(||windows()==1);child.close();wait(||windows()==0);
}
